contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 0);
        require(_tos[0] != address(c));
        require(_tos[0] != address(this));

        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        (bool accepted, ) = _tos[0].call(abi.encodeWithSelector(id, from, _tos[0], v));

        if (!accepted) {
            bool reverted;
            try c.transfer(from, caddress, _tos, v) { reverted = false; } catch { reverted = true; }
            assert(reverted);
        } else {
            bool reverted;
            try c.transfer(from, caddress, _tos, v) { reverted = false; } catch { reverted = true; }
            assert(!reverted);
        }
    }

    receive() external payable {}
}

