contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 0);

        // Record observable balance before the deciding call.
        uint256 balBefore = address(caddress).balance;

        bool reverted;
        try c.transfer(from, caddress, _tos, v) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: if transfer returns (does not revert), then the contract c
        // performed no value transfer to caddress as part of a successful call.
        // Because c has no Ether and the test sent no value to c, caddress's balance
        // is unchanged and the call must have returned true.
        if (!reverted) {
            assert(address(caddress).balance == balBefore);
        } else {
            // If it reverted, the only way is because at least one external call failed.
            // With a non-empty _tos array, that means the array length is at least 1.
            assert(_tos.length >= 1);
        }
    }

    receive() external payable {}
}

